//! The general pasteboard: its change counter and the password-manager privacy markers.

/// The general pasteboard's change count: it increments on every copy.
pub fn clipboard_change_count() -> i64 {
    objc2_app_kit::NSPasteboard::generalPasteboard().changeCount() as i64
}

/// True when the general pasteboard carries a marker that password managers (and other
/// apps) use for secrets: nspasteboard.org's concealed, transient and auto-generated
/// types, or 1Password's legacy marker. Such a copy must never leave this machine.
pub fn clipboard_is_private() -> bool {
    use objc2_app_kit::NSPasteboard;
    const MARKERS: [&str; 4] = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ];
    let types = NSPasteboard::generalPasteboard().types();
    types.is_some_and(|t| t.iter().any(|ty| MARKERS.contains(&ty.to_string().as_str())))
}
